    return `${beginning}`;
  }

  if (length === 0) {
    return `${beginning - 1},0`;
  }

  return `${beginning},${length}`;
}

export function splitLinesForDiff(text) {
  if (text.length === 0) {
    return [];
  }

  const lines = [];
  let lineStart = 0;

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];

    if (character === '\r') {
      lines.push(text.slice(lineStart, index));

      if (text[index + 1] === '\n') {
        index += 1;
      }

      lineStart = index + 1;
      continue;
    }

    if (character === '\n') {
      lines.push(text.slice(lineStart, index));
      lineStart = index + 1;
    }
  }

  if (lineStart < text.length) {
    lines.push(text.slice(lineStart));
  }

  return lines;
}

export function createUnifiedDiffLines(oldLines, newLines, contextSize = 3) {
  const diffLines = ['--- ', '+++ '];
  const matcher = new SequenceMatcher(oldLines, newLines);
  const groups = matcher.getGroupedOpcodes(contextSize);

  for (const group of groups) {
    const first = group[0];
    const last = group[group.length - 1];
    diffLines.push(
      `@@ -${formatRangeUnified(first[1], last[2])} +${formatRangeUnified(first[3], last[4])} @@`,
    );

    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') {
        for (let index = i1; index < i2; index += 1) {
          diffLines.push(` ${oldLines[index]}`);
        }

        continue;
      }

      if (tag === 'replace' || tag === 'delete') {
        for (let index = i1; index < i2; index += 1) {
          diffLines.push(`-${oldLines[index]}`);
        }
      }

      if (tag === 'replace' || tag === 'insert') {
        for (let index = j1; index < j2; index += 1) {
          diffLines.push(`+${newLines[index]}`);
        }
      }
    }
  }

  return diffLines;
}

export function createUnifiedDiff(oldText, newText, contextSize = 3) {
  return createUnifiedDiffLines(
    splitLinesForDiff(oldText),
    splitLinesForDiff(newText),
    contextSize,
  ).join('\n');
}

