const EMPTY_ARRAY = Object.freeze([]);

function compareBlocks(left, right) {
  return left.a - right.a || left.b - right.b;
}

export class SequenceMatcher {
  constructor(a, b, { autojunk = true } = {}) {
    this.autojunk = autojunk;
    this.a = [];
    this.b = [];
    this.b2j = new Map();
    this.matchingBlocks = null;
    this.opcodes = null;
    this.setSequences(a, b);
  }

  setSequences(a, b) {
    this.setSeq1(a);
    this.setSeq2(b);
  }

  setSeq1(a) {
    this.a = Array.isArray(a) ? a : [];
    this.matchingBlocks = null;
    this.opcodes = null;
  }

  setSeq2(b) {
    this.b = Array.isArray(b) ? b : [];
    this.matchingBlocks = null;
    this.opcodes = null;
    this.chainB();
  }

  chainB() {
    const b2j = new Map();

    for (let index = 0; index < this.b.length; index += 1) {
      const element = this.b[index];
      const indexes = b2j.get(element);

      if (indexes === undefined) {
        b2j.set(element, [index]);
      } else {
        indexes.push(index);
      }
    }

    if (this.autojunk && this.b.length >= 200) {
      const popularityThreshold = Math.floor(this.b.length / 100) + 1;
      const popular = [];

      for (const [element, indexes] of b2j.entries()) {
        if (indexes.length > popularityThreshold) {
          popular.push(element);
        }
      }

      for (const element of popular) {
        b2j.delete(element);
      }
    }

    this.b2j = b2j;
  }

  findLongestMatch(alo, ahi, blo, bhi) {
    let bestI = alo;
    let bestJ = blo;
    let bestSize = 0;
    let previousLengths = new Map();

    for (let indexA = alo; indexA < ahi; indexA += 1) {
      const currentLengths = new Map();
      const matches = this.b2j.get(this.a[indexA]) ?? EMPTY_ARRAY;

      for (const indexB of matches) {
        if (indexB < blo) {
          continue;
        }

        if (indexB >= bhi) {
          break;
        }

        const size = (previousLengths.get(indexB - 1) ?? 0) + 1;
        currentLengths.set(indexB, size);

        if (size > bestSize) {
          bestI = indexA - size + 1;
          bestJ = indexB - size + 1;
          bestSize = size;
        }
      }

      previousLengths = currentLengths;
    }

    while (bestI > alo && bestJ > blo && this.a[bestI - 1] === this.b[bestJ - 1]) {
      bestI -= 1;
      bestJ -= 1;
      bestSize += 1;
    }

    while (
      bestI + bestSize < ahi &&
      bestJ + bestSize < bhi &&
      this.a[bestI + bestSize] === this.b[bestJ + bestSize]
    ) {
      bestSize += 1;
    }

    return {
      a: bestI,
      b: bestJ,
      size: bestSize,
    };
  }

  getMatchingBlocks() {
    if (this.matchingBlocks !== null) {
      return this.matchingBlocks;
    }

    const queue = [[0, this.a.length, 0, this.b.length]];
    const matches = [];

    while (queue.length > 0) {
      const [alo, ahi, blo, bhi] = queue.pop();
      const match = this.findLongestMatch(alo, ahi, blo, bhi);

      if (match.size === 0) {
        continue;
      }

      if (alo < match.a && blo < match.b) {
        queue.push([alo, match.a, blo, match.b]);
      }

      if (match.a + match.size < ahi && match.b + match.size < bhi) {
        queue.push([match.a + match.size, ahi, match.b + match.size, bhi]);
      }

      matches.push(match);
    }

    matches.sort(compareBlocks);

    const nonAdjacent = [];
    let lastA = 0;
    let lastB = 0;
    let lastSize = 0;

    for (const match of matches) {
      if (lastA + lastSize === match.a && lastB + lastSize === match.b) {
        lastSize += match.size;
        continue;
      }

      if (lastSize > 0) {
        nonAdjacent.push({
          a: lastA,
          b: lastB,
          size: lastSize,
        });
      }

      lastA = match.a;
      lastB = match.b;
      lastSize = match.size;
    }

    if (lastSize > 0) {
      nonAdjacent.push({
        a: lastA,
        b: lastB,
        size: lastSize,
      });
    }

    nonAdjacent.push({
      a: this.a.length,
      b: this.b.length,
      size: 0,
    });

    this.matchingBlocks = nonAdjacent;
    return this.matchingBlocks;
  }

  getOpcodes() {
    if (this.opcodes !== null) {
      return this.opcodes;
    }

    const opcodes = [];
    let indexA = 0;
    let indexB = 0;

    for (const block of this.getMatchingBlocks()) {
      const nextA = block.a;
      const nextB = block.b;
      const size = block.size;
      let tag = '';

      if (indexA < nextA && indexB < nextB) {
        tag = 'replace';
      } else if (indexA < nextA) {
        tag = 'delete';
      } else if (indexB < nextB) {
        tag = 'insert';
      }

      if (tag !== '') {
        opcodes.push([tag, indexA, nextA, indexB, nextB]);
      }

      if (size > 0) {
        opcodes.push(['equal', nextA, nextA + size, nextB, nextB + size]);
      }

      indexA = nextA + size;
      indexB = nextB + size;
    }

    this.opcodes = opcodes;
    return this.opcodes;
  }

  getGroupedOpcodes(contextSize = 3) {
    const opcodes = this.getOpcodes().slice();

    if (opcodes.length === 0) {
      return [];
    }

    if (opcodes[0][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = opcodes[0];
      opcodes[0] = [tag, Math.max(i1, i2 - contextSize), i2, Math.max(j1, j2 - contextSize), j2];
    }

    const lastIndex = opcodes.length - 1;

    if (opcodes[lastIndex][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = opcodes[lastIndex];
      opcodes[lastIndex] = [tag, i1, Math.min(i2, i1 + contextSize), j1, Math.min(j2, j1 + contextSize)];
    }

    const groups = [];
    const doubleContext = contextSize * 2;
    let group = [];

    for (const opcode of opcodes) {
      let [tag, i1, i2, j1, j2] = opcode;

      if (tag === 'equal' && i2 - i1 > doubleContext) {
        group.push([tag, i1, Math.min(i2, i1 + contextSize), j1, Math.min(j2, j1 + contextSize)]);
        groups.push(group);
        group = [];
        i1 = Math.max(i1, i2 - contextSize);
        j1 = Math.max(j1, j2 - contextSize);
      }

      group.push([tag, i1, i2, j1, j2]);
    }

    if (!(group.length === 1 && group[0][0] === 'equal')) {
      groups.push(group);
    }

    return groups;
  }
}

