import { buildError, buildHelp } from './messages.mjs';

const OPTION_TO_KEY = {
  '--a': 'a',
  '--b': 'b',
};

const NEGATIVE_NUMBER_PATTERN = /^-(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

function isNegativeNumberToken(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function isOptionLikeToken(token) {
  if (token === '--') {
    return true;
  }

  if (!token.startsWith('-') || token === '-') {
    return false;
  }

  return !isNegativeNumberToken(token);
}

function splitInlineLongOption(token) {
  if (!token.startsWith('--')) {
    return null;
  }

  const equalsIndex = token.indexOf('=');

  if (equalsIndex === -1) {
    return null;
  }

  return {
    option: token.slice(0, equalsIndex),
    value: token.slice(equalsIndex + 1),
  };
}

function buildExpectedArgumentError(programName, option) {
  return {
    kind: 'error',
    exitCode: 2,
    text: buildError(programName, `argument ${option}: expected one argument`),
  };
}

export function parseArguments(argv, programName) {
  const values = {
    a: undefined,
    b: undefined,
  };
  const extras = [];
  let expectedOption = null;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (expectedOption !== null) {
      if (token === undefined || isOptionLikeToken(token)) {
        return buildExpectedArgumentError(programName, expectedOption);
      }

      values[OPTION_TO_KEY[expectedOption]] = token;
      expectedOption = null;
      continue;
    }

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        exitCode: 0,
        text: buildHelp(programName),
      };
    }

    const inlineOption = splitInlineLongOption(token);

    if (inlineOption !== null) {
      if (inlineOption.option in OPTION_TO_KEY) {
        values[OPTION_TO_KEY[inlineOption.option]] = inlineOption.value;
      } else {
        extras.push(token);
      }

      continue;
    }

    if (token in OPTION_TO_KEY) {
      expectedOption = token;
      continue;
    }

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    extras.push(token);
  }

  if (expectedOption !== null) {
    return buildExpectedArgumentError(programName, expectedOption);
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      text: buildError(programName, `the following arguments are required: ${missing.join(', ')}`),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      text: buildError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    exitCode: 0,
    values,
  };
}

