import { parseArguments } from './lib/cli/parser.mjs';
import { getProgramName } from './lib/cli/program-name.mjs';
import { deepDiffStrings } from './lib/deepdiff/string-deepdiff.mjs';
import { pythonRepr } from './lib/format/python-repr.mjs';

function getBaseFileUrl(currentWorkingDirectory) {
  return `file://${currentWorkingDirectory.endsWith('/') ? currentWorkingDirectory : `${currentWorkingDirectory}/`}`;
}

export function main(argv = process.argv.slice(2)) {
  const programName = getProgramName(process.argv[1] ?? '');
  const parsed = parseArguments(argv, programName);

  if (parsed.kind === 'help' || parsed.kind === 'error') {
    const stream = parsed.kind === 'help' ? process.stdout : process.stderr;
    stream.write(parsed.text);
    return parsed.exitCode;
  }

  const result = deepDiffStrings(parsed.values.a, parsed.values.b);
  process.stdout.write(`${pythonRepr(result)}\n`);
  return 0;
}

const invokedModuleUrl = process.argv[1]
  ? new URL(process.argv[1], getBaseFileUrl(process.cwd())).href
  : '';

if (import.meta.url === invokedModuleUrl) {
  process.exitCode = main();
}

